-- UNDO for 20261107-0200-tax-return-signed-fax-box.sql. Puts the "Signed" layout back to the item-5 version (the "Send Fax to IRS" link instead of the
-- return fax box). Only fires on the exact new row (never overwrites a later edit). A fax already sent from the box stays on record; the box only
-- disappears from the screen.

UPDATE pipeline_stages
SET stage_layout = '{"components": [{"type": "esign_panel", "title": "Signed return", "readOnly": true, "rename": "Tax Return {year} - {company_name}", "helpText": "The client signed. Open it to see or download the signed copy (a copy is also filed in the company storage and shown to the client)."}, {"type": "document_viewer"}, {"type": "action_buttons", "actions": [{"key": "file_with_irs", "label": "File with IRS", "target": "TR Filed", "confirm": "Mark this return as filed with the IRS? The client will see it as Filed and their tax banner will go away."}]}, {"type": "fax_irs"}, {"type": "chat"}], "description": "The client signed the return. Fax it to the IRS, then mark it filed."}'::jsonb
WHERE service_type = 'Tax Return' AND stage_name = 'Signed'
  AND stage_layout = '{"components": [{"type": "esign_panel", "title": "Signed return", "readOnly": true, "rename": "Tax Return {year} - {company_name}", "helpText": "The client signed. Open it to see or download the signed copy (a copy is also filed in the company storage and shown to the client)."}, {"type": "return_fax_panel"}, {"type": "document_viewer"}, {"type": "action_buttons", "actions": [{"key": "file_with_irs", "label": "File with IRS", "target": "TR Filed", "confirm": "Mark this return as filed with the IRS? The client will see it as Filed and their tax banner will go away."}]}, {"type": "chat"}], "description": "The client signed the return. Fax it to the IRS from here; the job is filed by itself once the fax is delivered."}'::jsonb;
